def dedupe_vacant_places(apps, schema_editor):
    """Перед уникальностью VacantPlace.program: оставить по одной записи на программу (самую свежую)."""
    VacantPlace = apps.get_model("sveden", "VacantPlace")
    seen = set()
    for place in VacantPlace.objects.order_by("program_id", "-updated_at", "-pk"):
        if place.program_id in seen:
            place.delete()
        else:
            seen.add(place.program_id)


